    g:[
      {more:["This time next month I’ll be working in a different department.","By December we’ll have replaced every unit in the fleet.","I don’t think prices will fall, but they probably won’t rise much either.","At ten tomorrow they’ll be presenting to the board.","By the time you land, we’ll have finished the setup.","She’ll have been with the company ten years in March."],
       fix:[{wrong:"By the time you will arrive, we’ll have started.", right:"By the time you arrive, we’ll have started.", why:"A time clause never takes a future form."},
            {wrong:"At ten tomorrow I will work.", right:"At ten tomorrow I’ll be working.", why:"An action in progress at a future moment takes the future continuous."},
            {wrong:"By June I will finish the course.", right:"By June I’ll have finished the course.", why:"Completion before a deadline takes the future perfect."}],
       drill:{name:"Three futures", prompt:"For each moment, produce a prediction with will, an action in progress with the future continuous, and a completed result with the future perfect.",
        items:["this time tomorrow","by the end of the month","in five years","by the time you get back","at midnight tonight"]},
       dialogue:[{sp:"A", line:"Will the fleet be ready for the inspection?"},{sp:"B", line:"By then we’ll have replaced every unit."},{sp:"A", line:"And the paperwork?"},{sp:"B", line:"I’ll be working on it all week. It won’t be finished before Thursday, but it’ll be done."}],
       contrast:{title:"Which future", cols:["Meaning","Form","Example"], rows:[["prediction","will + verb","Prices will rise."],["in progress at a future point","will be + -ing","I’ll be flying at ten."],["completed before a deadline","will have + participle","By June I’ll have finished."],["duration up to a future point","will have been + -ing","By May I’ll have been studying two years."],["plan already made","be going to","We’re going to move."],["scheduled event","present simple","The train leaves at six."]]},
       sound:"“Will have” contracts twice in speech — “I’ll’ve finished” /aɪləv/ — so the whole future perfect can sound like a single syllable before the participle."},
      {more:["It happened during the night, some time before three.","We met in 2019 and worked together for two years.","I left the company two years ago.","She’s been in the role since March.","The contract ran from January to September.","We haven’t spoken since the conference."],
       fix:[{wrong:"I work here since 2019.", right:"I’ve worked here since 2019.", why:"“Since” with a period up to now requires a perfect tense."},
            {wrong:"during three hours", right:"for three hours", why:"“During” takes a named period; a length of time takes “for”."},
            {wrong:"I have left two years ago.", right:"I left two years ago.", why:"“Ago” marks a finished point and takes the simple past."}],
       drill:{name:"Place it in time", prompt:"Describe each event three times, using a different time expression each time, and adjust the tense to match.",
        items:["the last time you moved house","a course you finished","a job you started","a trip you took","a friendship that began"]},
       dialogue:[{sp:"A", line:"How long have you been in maintenance?"},{sp:"B", line:"Since 2019 — about seven years."},{sp:"A", line:"And before that?"},{sp:"B", line:"I worked in logistics for three years, and I left just before the merger."}],
       contrast:{title:"Time expressions and their tenses", cols:["Expression","Takes","Tense"], rows:[["during","a named period","past or present"],["in","a month, year, season","simple past"],["on","a day or date","simple past"],["ago","a length of time back","simple past"],["for","a length of time","any, incl. perfect"],["since","a starting point","perfect only"]]},
       sound:"“For” is reduced to /fə/ before a consonant and “since” keeps its /s/ clearly. In fast speech “for” almost disappears, so the number after it must be clear."} ],
    dyn:[
      {name:"Five-year projection", mode:"Groups of 4", minutes:"12 min", how:"Groups make six predictions about their city, workplace or industry, one for each row of the future table, then defend the two boldest to another group.", payoff:"The table forces the future perfect and continuous, which learners avoid."},
      {name:"By the time you get back", mode:"Pairs", minutes:"8 min", how:"A announces a trip; B says what will have happened and what they will be doing at three specific moments while A is away.", payoff:"Both future forms are needed by the frame itself."},
      {name:"Timeline interview", mode:"Whole class, moving", minutes:"12 min", how:"Students draw a personal timeline with six points and interview each other about it, using a different time expression in every question.", payoff:"Puts the whole expression set into questions, not just answers."},
      {name:"For or since", mode:"Whole class", minutes:"6 min", how:"Teacher calls a time reference; students respond FOR or SINCE and produce a full sentence with the correct tense.", payoff:"Fast correction of the highest-frequency error in the node."} ],
    wr:{title:"Where this is heading", brief:"Write about a plan or project. Part one: predict its state at three future points, using will, the future continuous and the future perfect. Part two: give the background using at least four different past time expressions.", length:"12 sentences · about 170 words", criteria:["All three future forms used correctly, one each at minimum.","No future form inside a time clause.","Four different past time expressions with the tense each requires."]},
    hw:{title:"Forward and back", task:"Write six sentences about your life at three future points (next week, next year, in five years), using a different future form for each pair. Then write six about past events, each with a different time expression."},
    test:[
      {q:"By the time the inspection starts, we ___ every panel.", options:["will have checked","will check","will be checking"], answer:0, explain:"Completion before a future deadline takes the future perfect."},
      {q:"At ten tomorrow I ___ to the board.", options:["will be presenting","will present","present"], answer:0, explain:"An action in progress at a future moment takes the future continuous."},
      {q:"By the time you ___ , we’ll have started.", options:["arrive","will arrive","are arriving"], answer:0, explain:"Time clauses never take a future form."},
      {q:"I left that company two years ___ .", options:["ago","before","since"], answer:0, explain:"“Ago” counts back from now and takes the simple past."},
      {q:"She’s been in the role ___ March.", options:["since","for","during"], answer:0, explain:"“Since” marks the starting point of a period reaching to now."} ],
